local yF=(getgenv and getgenv()) or _ENV or _G
local sj={} for i=97,122 do sj[#sj+1]=string.char(i) end
local id={12,15,1,4,19,20,18,9,14,7}
local Ef="" for i=1,#id do Ef=Ef..sj[id[i]] end
local qV=yF and yF[Ef]
local Mf=type(qV)=="function"
if Mf then
local qp={8,15,15,11,6,21,14,3,20,9,15,14}
local mx="" for i=1,#qp do mx=mx..sj[qp[i]] end
local gn={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local ET="" for i=1,#gn do ET=ET..sj[gn[i]] end
local KN=yF[mx]
local qB=yF[ET]
local AX=false
if type(KN)=="function" and type(qB)=="function" then
local gf=function() return 5 end
local uB=pcall(KN,gf,function() return -777 end)
if uB and gf()==-777 then
local sb=pcall(qB,gf)
AX=(sb and gf()==5)
end
if not AX then pcall(qB,gf) end
if not AX and type(yF.math)=="table" and type(yF.math.abs)=="function" then
local Sp=yF.math.abs
if Sp(5)==5 then
local qt,Od=pcall(KN,Sp,function() return -777 end)
if qt and Sp(5)==-777 then
local kH=pcall(qB,Sp)
AX=(kH and Sp(5)==5)
if not AX then pcall(qB,Sp) yF.math.abs=(type(Od)=="function" and Od) or function(v) if v<0 then return -v end return v end end
end
end
end
if AX then
local Mj={qV,KN,qB}
local Cl=yF.string
if type(Cl)=="table" then
Mj[#Mj+1]=Cl.char Mj[#Mj+1]=Cl.byte Mj[#Mj+1]=Cl.sub Mj[#Mj+1]=Cl.rep Mj[#Mj+1]=Cl.len
end
if type(yF.table)=="table" and yF.table.concat then Mj[#Mj+1]=yF.table.concat end
if yF.pcall then Mj[#Mj+1]=yF.pcall end
if type(yF.math)=="table" and yF.math.floor then Mj[#Mj+1]=yF.math.floor end
for sP=1,#Mj do local zt=Mj[sP] if type(zt)=="function" then pcall(qB,zt) end end
end
end
end
if not Mf then return nil end

